// Общие шаги для тестов непрозрачности модальных окон (план specs/modals.md). Только чтение: окна открываются и закрываются Esc,
// ничего не вводится и не сохраняется (JobDetail автосохраняет — поэтому в его окнах ничего не трогаем).
import { expect, Locator, Page, TestInfo } from '@playwright/test';
import * as path from 'path';

/** Сессия admin — путь от этого файла, а не от cwd. */
export const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');

/** Устройства, проверенные вручную: десктоп Chrome 1440×900 и Android Pixel 7. */
export const DEVICES = ['@desktop', '@android'] as const;

/** Свойства затемняющего слоя: элемент position:fixed на весь экран, data-state="open", с непрозрачным фоном. */
async function overlayStyles(page: Page) {
  return page.evaluate(() =>
    [...document.querySelectorAll('body *')]
      .filter((e) => {
        if (e.getAttribute('role') === 'dialog' || e.getAttribute('data-state') !== 'open') return false;
        const s = getComputedStyle(e);
        const r = e.getBoundingClientRect();
        return s.position === 'fixed' && r.width >= innerWidth - 1 && r.height >= innerHeight - 1 && s.backgroundColor !== 'rgba(0, 0, 0, 0)';
      })
      .map((e) => {
        const s = getComputedStyle(e);
        return { bg: s.backgroundColor, backdrop: s.backdropFilter || (s as unknown as { webkitBackdropFilter?: string }).webkitBackdropFilter || '' };
      }),
  );
}

/**
 * Окно непрозрачное, страница позади затемнена.
 * Факты ручной проверки 14.10 (светлая тема): панель rgb(255,255,255), opacity 1;
 * слой позади rgba(2,6,23,0.35) + backdrop-filter blur(4px).
 */
export async function expectOpaqueModalOverDimmedPage(page: Page, dialog: Locator) {
  await expect(dialog).toBeVisible();
  // Окно появляется с анимацией (opacity растёт) — ждём окончания, без пауз.
  await expect.poll(() => dialog.evaluate((e) => getComputedStyle(e).opacity)).toBe('1');
  await expect.poll(() => dialog.evaluate((e) => getComputedStyle(e).backgroundColor)).toBe('rgb(255, 255, 255)');

  await expect.poll(async () => (await overlayStyles(page)).length).toBeGreaterThan(0);
  const [overlay] = await overlayStyles(page);
  const alpha = Number(/rgba\([^)]*,\s*([\d.]+)\)/.exec(overlay.bg)?.[1] ?? '1');
  expect(alpha, `затемнение позади окна (${overlay.bg})`).toBeGreaterThanOrEqual(0.3);
  expect(overlay.backdrop, 'размытие страницы позади окна').toContain('blur(');
}

/** Закрыть окно Esc (клик по затемнению окно не закрывает — в тест не входит) и убедиться, что окна и затемнения нет. */
export async function closeWithEsc(page: Page, dialog: Locator) {
  await page.keyboard.press('Escape');
  await expect(dialog).toBeHidden();
  await expect.poll(async () => (await overlayStyles(page)).length).toBe(0);
}

/** «Create new» в меню. На телефоне меню сначала открывается кнопкой «Open navigation». */
export async function openCreateNew(page: Page, testInfo: TestInfo) {
  await page.goto('/dashboard');
  if (testInfo.project.use.isMobile) {
    await page.getByRole('button', { name: 'Open navigation' }).filter({ visible: true }).first().click();
  }
  await page.getByRole('button', { name: 'Create new' }).filter({ visible: true }).first().click();
}

/** Job Details любой существующей работы (первая строка списка Jobs), вкладка Items. */
export async function openJobItemsTab(page: Page) {
  await page.goto('/jobs');
  await page.getByRole('cell', { name: /^JOB-\d+$/ }).first().click();
  await page.waitForURL(/\/JobDetail\?id=/);
  const url = new URL(page.url());
  url.searchParams.set('tab', 'items');
  await page.goto(url.toString());
  await expect(page.getByRole('button', { name: 'Price Book', exact: true }).first()).toBeVisible();
}
